function icon(name,attrs){
 const body=ICONS[name];
 if(!body){console.warn('Unknown icon',name);return ''}
 const extra=Object.entries(attrs||{}).filter(([k])=>k!=='class').map(([k,v])=>` ${k}="${v}"`).join('');
 return `<svg class="hi${attrs?.class?' '+attrs.class:''}" viewBox="0 0 24 24" aria-hidden="true"${extra}>${body}</svg>`;
}

// Static markup carries data-icon; the drawing arrives here, so the pages stay readable.
function paintIcons(scope){
 for(const host of (scope||document).querySelectorAll('[data-icon]')) host.outerHTML=icon(host.dataset.icon);
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>paintIcons());
else paintIcons();
